grid = [[4]*13 for _ in range(20)]
# Given scattered target cells
anchors = [(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# Template offsets from its central 5 at row 12, col 7; None means untouched background.
pattern = [[None,5,5],[8,5,8],[8,5,0]]
for ar,ac in anchors:
    for dr,row in enumerate(pattern):
        for dc,val in enumerate(row):
            if val is not None:
                grid[ar+dr-1][ac+dc-1] = val
# Existing exemplar/source motif and its anchor point
for r,c,v in [(11,7,5),(11,8,5),(12,6,8),(12,7,5),(12,8,8),(13,6,8),(13,7,5),(13,8,0)]:
    grid[r][c] = v
print(len(grid), {len(row) for row in grid})
print('[' + ','.join('['+','.join(map(str,row))+']' for row in grid) + ']')

g=[[4]*13 for _ in range(20)]
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# Seed pattern coordinates relative to its center at (12,7); include 4 at top-left implicitly as background.
pattern={(-1,0):5,(-1,1):5,(0,-1):8,(0,0):5,(0,1):8,(1,-1):8,(1,0):5,(1,1):0}
for r,c in markers:
    for (dr,dc),v in pattern.items():
        g[r+dr][c+dc]=v
# Preserve seed, same source motif.
for r,c,v in [(11,7,5),(11,8,5),(12,6,8),(12,7,5),(12,8,8),(13,6,8),(13,7,5),(13,8,0)]:
    g[r][c]=v
import json
assert len(g)==20 and all(len(row)==13 for row in g)
print(json.dumps(g,separators=(',',':')))
